exit 40 23 W L-R02-05>from_river
exit 41 23 W L-R02-05>from_river
mark from_W 40 21 N
mark from_river 40 21 N
mark from_shaft 39 4 W
mark from_KT-01 39 4 W
mark grate_w 12 4 E
mark shaft_bottom 38 7 W
mark pump 5 8 N
mark tunnel_w 13 12 E
mark hall 13 8 E
drain 12 5 31 17 cond="KT_POWER == 1"
flood 14 11 21 3 cond="KT_TUNNEL == 1 and KT_POWER != 1"
dark cond="KT_POWER == 0 or KT_POWER == 3"
# ---------------------------------------------------------------- 펌프실 · 사육사 휴게실(쉼터)
prop pump_kt 3 4 cond="KT_POWER == 0"
prop pump_kt 3 4 state=drain cond="KT_POWER == 1"
prop pump_kt 3 4 state=lift cond="KT_POWER == 2"
prop pump_kt 3 4 state=gone cond="KT_POWER == 3"
text 3 5 "비상 발전기와 배수 펌프." w=2 scene=KT_PUMP
prop w_staff_phone_kt 7 1 cond="KT_RING2 == 0"
prop w_staff_phone_kt 7 1 state=lit cond="KT_RING2 >= 1"
text 7 2 "관내 직원 인터폰. '전망대 9'." scene=KT_PHONE2
prop w_feedlog_kt 9 1
text 9 2 "사육사 먹이 주기 일지." scene=KT_FEEDLOG
prop note_ground 6 10
text 6 10 "발전기 옆 상자에 쪽지가 테이프로 붙었다." scene=KT_NOTE
prop locker_row2 1 10
box 1 10 locker name="사육사 사물함"
text 2 10 "사물함 문 안쪽." scene=KT_LOCKER
prop cot 7 11
text 9 11 "사육사 휴게실 구석." scene=KT_REST
prop grate_gate_kt 11 4 cond="KT_GRATE == 0"
text 11 4 "직원 통로 철망 문." scene=KT_GRATE
# ---------------------------------------------------------------- 수조 줄 A(발판 아래 — 발판과 홀을 가른다)
prop w_coral_kt 14 1
prop w_coral_kt 30 1
text 14 2 "산호 벽 '서울의 바다'. 철망 발판이 그 앞을 지난다 — 관람객은 못 올라가는 높이." w=2
prop tank_kt 12 5
prop tank_kt 16 5
prop tank_kt 20 5 state=dry
prop tank_kt 24 5
prop tank_kt 28 5
prop tank_kt 32 5
text 20 4 "발판 아래 빈 수조. 마른 수초가 바닥에 누웠다." w=4
text 30 4 "수조 위 철망 발판. 녹슨 격자 틈으로 아래 물빛 — 사육사가 다니던 길. 물 밖이라 수염이 닿지 않는다." w=3
# ---------------------------------------------------------------- 수조 줄 B · C(유리 터널 양쪽 유리)
prop tank_kt 14 9
prop tank_kt 18 9
prop tank_kt 22 9 state=broken
prop tank_kt 26 9
prop tank_kt 30 9
prop tank_kt 14 14
prop tank_kt 18 14
prop tank_kt 22 14
prop tank_kt 26 14
prop tank_kt 30 14 state=dry
text 18 11 "유리 터널. 양쪽 유리 너머 물빛이 일렁인다. 큰 그림자 하나가 유리 바로 너머에서 나를 따라 헤엄친다 — 보이지만 아직 닿지 않는다." w=3 scene=KT_TUNNEL
text 22 10 "한강의 물고기 수조. 앞 유리에 별 모양 금. 금 간 자리에서 물방울이 똑똑." w=4
prop rubble 38 12
prop rubble 13 19
# ---------------------------------------------------------------- 승강로 바닥(꺼진 칸 — 물에 잠긴 칸 지붕 · 점검 사다리)
text 38 5 "승강로 바닥. 칸 지붕이 허리 물에 잠겼다. 벽에 점검 사다리가 위로 — 로비 승강기 4번 문." w=2 scene=KT_SHAFTUP cond="KT_POWER != 1"
text 38 5 "물이 빠진 승강로 바닥. 찌그러진 칸이 기울어 있다. 문이 비틀려 열렸다." w=2 scene=KT_CAR cond="KT_POWER == 1"
text 40 6 "꺼진 해치 구멍 — 물속 칸." scene=KT_CAR cond="KT_HATCH == 1 and KT_POWER != 1"
prop crate_o 40 8 cond="KT_POWER == 1 or KT_HATCH == 1"
box 40 8 bag name="꺼진 칸 — 승객들의 소지품" cond="KT_POWER == 1 or KT_HATCH == 1"
# ---------------------------------------------------------------- 둔치 비상구
text 40 21 "비상구 계단참. 위에서 강바람과 물비린내. 아래 허리 물 속에서 무언가 수염을 흔든다." w=2
# ---------------------------------------------------------------- 메기 새끼(물속 매복 — 수염: 물에 발 담근 사람은 웅크려도 안다)
enemy CR-130 24 8 lurk=1 lv=4 cond="KT_POWER != 1"
enemy CR-130 28 18 lurk=1 lv=4 cond="KT_POWER != 1"
enemy CR-130 36 19 lurk=1 lv=4 cond="KT_POWER != 1"
